<?php $search=mb_substr(trim((string)($_GET['q']??'')),0,100);$filter=(string)($_GET['status']??'');$sql='SELECT o.*,c.name customer,(SELECT SUM(quantity) FROM items i WHERE i.order_id=o.id) units FROM orders o JOIN customers c ON c.id=o.customer_id WHERE (o.code LIKE ? OR c.name LIKE ?)';$args=['%'.$search.'%','%'.$search.'%'];if(in_array($filter,['draft','confirmed','production','ready','shipped','cancelled'],true)){$sql.=' AND o.status=?';$args[]=$filter;}$list=rows($sql.' ORDER BY o.id DESC LIMIT 200',$args); ?>
<div class="toolbar"><form method="get" class="inline"><input type="hidden" name="page" value="orders"><input name="q" placeholder="Order or customer" value="<?=e($search)?>"><select name="status"><option value="">All statuses</option><?php foreach(['draft','confirmed','production','ready','shipped','cancelled'] as $s): ?><option <?=$s===$filter?'selected':''?>><?=e($s)?></option><?php endforeach ?></select><button class="secondary">Search</button></form><a class="button" href="index.php?page=order">+ New order</a></div>
<section class="card table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Units</th><th>Status</th><th>Due date</th><th>Priority</th></tr></thead><tbody><?php foreach($list as $o): ?><tr><td><a href="index.php?page=order&id=<?=$o['id']?>"><?=e($o['code'])?></a></td><td><?=e($o['customer'])?></td><td><?=e($o['units']??0)?></td><td><?php badge($o['status']); ?></td><td><?=e($o['due_date']??'Unscheduled')?></td><td><?=e($o['priority'])?></td></tr><?php endforeach ?><?php if(!$list): ?><tr><td colspan="6">No orders found. Create a customer, then add your first order.</td></tr><?php endif ?></tbody></table><p class="muted">Showing up to 200 matches. Search to narrow the list.</p></section>
